27	// ResolvePackageFromName resolves a registry package from user input. User input may be in the following forms:
28	//
29	//	<source>/<publisher>/<name> -> [<source>/<publisher>/<name>]
30	//
31	//	<publisher>/<name>          -> [private/<publisher>/<name>, pulumi/<publisher>/<name>]
32	//
33	//	<name>                      -> [private/*/<name>, pulumi/*/<name>]
34	//
35	// The returned error will include [NotFoundError] if and only if ResolvePackageFromName
36	// has determined that registry does not contain a matching package.
37	//
38	// If ResolvePackageFromName could not parse name into a fragment kind, it will return an
39	// error that includes [InvalidIdentifierError].
40	//
41	// When ResolvePackageFromName is unable to find a corresponding package (and
42	// [NotFoundError] is returned), a list of similar packages *may* be available from
43	// calling [GetSuggestedPackages] on the returned error.
44	func ResolvePackageFromName(
45		ctx context.Context, registry Registry, name string, version *semver.Version,
46	) (apitype.PackageMetadata, error) {
47		parts := strings.Split(name, "/")
48		switch len(parts) {
49		case 3:
50			p, err := registry.GetPackage(ctx, parts[0], parts[1], parts[2], version)
51			return p, err
52		case 2:
53			// First check on "private"
54			pkg, err := registry.GetPackage(ctx, "private", parts[0], parts[1], version)
55			if err == nil {
56				return pkg, nil
57			} else if !errors.Is(err, ErrNotFound) && !errors.Is(err, ErrUnauthorized) && !errors.Is(err, ErrForbidden) {
58				return apitype.PackageMetadata{}, fmt.Errorf("unable to check on private/%s: %w", name, err)
59			}
60	
61			// Then check on "pulumi"
62			pkg, err = registry.GetPackage(ctx, "pulumi", parts[0], parts[1], version)
63			if err == nil {
64				return pkg, nil
65			} else if !errors.Is(err, ErrNotFound) {
66				return apitype.PackageMetadata{}, fmt.Errorf("unable to check on pulumi/%s: %w", name, err)
67			}
68	
69			// Both "private" and "pulumi" didn't exist, so we have successfully resolved to NotFound.
70			return apitype.PackageMetadata{}, fmt.Errorf("could not resolve %s: %w", name, ErrNotFound)
71		case 1:
72			var pulumiPackageMetadata *apitype.PackageMetadata
73			var privatePackageMetadata []apitype.PackageMetadata
74			var suggested []apitype.PackageMetadata
75			for meta, err := range registry.ListPackages(ctx, &name) {
76				if err != nil {
77					return apitype.PackageMetadata{}, err
78				}
79	
80				if meta.Source == "private" {
81					privatePackageMetadata = append(privatePackageMetadata, meta)
82				} else if meta.Source == "pulumi" && meta.Publisher == "pulumi" {
83					// We don't break here, since we might still have a dominant source: the key in "private".
84					pulumiPackageMetadata = &meta
85				} else {
86					suggested = append(suggested, meta)
87				}
88			}
89	
90			if len(privatePackageMetadata) > 1 {
91				err := fmt.Errorf("%q is ambiguous, it matches both %s/%s/%s and %d other packages",
92					name,
93					privatePackageMetadata[0].Source, privatePackageMetadata[0].Publisher, privatePackageMetadata[0].Name,
94					len(privatePackageMetadata)-1,
95				)
96				if len(privatePackageMetadata) == 2 {
97					err = fmt.Errorf("%q is ambiguous, it matches both %s/%s/%s and %s/%s/%s",
98						name,
99						privatePackageMetadata[0].Source, privatePackageMetadata[0].Publisher, privatePackageMetadata[0].Name,
100						privatePackageMetadata[1].Source, privatePackageMetadata[1].Publisher, privatePackageMetadata[1].Name,
101					)
102				}
103	
104				return apitype.PackageMetadata{},
105					errorSuggestedPackages{
106						err:      err,
107						packages: privatePackageMetadata,
108					}
109			}
110	
111			// Search by name returns the latest package versions with the correct name.
112			//
113			// If a version was specified, we need to fetch that specific version with GetPackage.
114			applyVersion := func(meta apitype.PackageMetadata) (apitype.PackageMetadata, error) {
115				if version == nil || meta.Version.Equals(*version) {
116					return meta, nil
117				}
118				m, err := registry.GetPackage(ctx, meta.Source, meta.Publisher, meta.Name, version)
119				if err == nil {
120					return m, nil
121				}
122				if errors.Is(err, ErrNotFound) {
123					return apitype.PackageMetadata{}, versionMismatchError{
124						found: meta, desired: *version,
125						err: errorSuggestedPackages{
126							packages: []apitype.PackageMetadata{meta},
127							err:      ErrNotFound,
128						},
129					}
130				}
131				return apitype.PackageMetadata{}, err
132			}
133	
134			if len(privatePackageMetadata) == 1 {
135				return applyVersion(privatePackageMetadata[0])
136			}
137			if pulumiPackageMetadata != nil {
138				return applyVersion(*pulumiPackageMetadata)
139			}
140			var versionStr string
141			if version != nil {
142				versionStr = "@" + version.String()
143			}
144			return apitype.PackageMetadata{}, fmt.Errorf(
145				"%w: %s%s does not match a registry package", errorSuggestedPackages{
146					packages: suggested,
147					err:      ErrNotFound,
148				}, name, versionStr)
149		default:
150			return apitype.PackageMetadata{}, InvalidIdentifierError{name}
151		}
152	}
153	
154	func GetSuggestedPackages(err error) []apitype.PackageMetadata {
155		var suggestions errorSuggestedPackages
156		errors.As(err, &suggestions)
157		return suggestions.packages
158	}
159	
160	type errorSuggestedPackages struct {
161		err      error
162		packages []apitype.PackageMetadata
163	}
164	
165	func (err errorSuggestedPackages) Error() string {
166		return err.err.Error()
167	}
168	
169	func (err errorSuggestedPackages) Unwrap() error {
170		return err.err
171	}
172	
173	// An error indicating that the registry contains the correct "package", but not the
174	// correct "package version".
175	type versionMismatchError struct {
176		found   apitype.PackageMetadata
177		desired semver.Version
178		err     error
179	}
180	
181	func (err versionMismatchError) Error() string {
182		return fmt.Sprintf("%s/%s/%s exists, but version %s was not found",
183			err.found.Source, err.found.Publisher, err.found.Name, err.desired,
184		)
185	}
186	
187	func (err versionMismatchError) Unwrap() error { return err.err }
188	
189	type InvalidIdentifierError struct{ given string }
190	
191	func (err InvalidIdentifierError) Error() string {
192		if err.given == "" {
193			return "invalid identifier"
194		}
195		return fmt.Sprintf("invalid identifier: found %q", err.given)
196	}
