123	func (s *Source) getCloudTemplates(
124		ctx context.Context, templateName string,
125		wg *sync.WaitGroup, e env.Env,
126	) {
127		if !e.GetBool(env.DisableRegistryResolve) {
128			s.getRegistryTemplates(ctx, e, templateName)
129			return
130		}
131	
132		// Use the old org templates based API.
133		//
134		// This path can be removed when we are confident in registry resolution. We will
135		// always need to maintain a way to access templates without the service, but we
136		// should only need to maintain one way to access templates through the service.
137		s.getOrgTemplates(ctx, templateName, wg, e)
138	}
