189		// To help with disambiguation we show the "origin" of templates. For VCS backed templates we show the repo slug.
190		// For registry backed templates we show the publisher (= organisation name).
191		//
192		// Note that the default templates from https://github.com/pulumi/templates are not included here, they are not
193		// `registryTemplate` instances, so these are shown without extra annotation.
194		switch r.t.Source {
195		case "github", "gitlab":
196			nameParts := strings.SplitN(r.t.Name, "/", 3)
197			name := nameParts[len(nameParts)-1]
198			if r.t.RepoSlug != nil {
199				return fmt.Sprintf("%s [%s]", name, *r.t.RepoSlug)
200			}
201			return name
202		default:
203			if r.GetPublisher() != "" {
204				return fmt.Sprintf("%s [%s]", r.t.Name, r.GetPublisher())
205			}
206			return r.t.Name
207		}
208	}
