// getVersionedRegistryTemplate resolves a template at a specific version.
//
// Unlike the (unversioned) list-based resolution, a version pins the template to an exact
// release fetched through the registry's GetTemplate API.
func (s *Source) getVersionedRegistryTemplate(ctx context.Context, r registry.Registry, urlInfo *registry.URLInfo) {
	version := urlInfo.Version()

	// Reconstruct the human-readable identifier from the parsed coordinates so that
	// [registry.ResolveTemplateFromName] can resolve any of the supported forms.
	id := urlInfo.Name()
	if urlInfo.Publisher() != "" {
		id = urlInfo.Publisher() + "/" + id
		if urlInfo.Source() != "" {
			id = urlInfo.Source() + "/" + id
		}
	}

	template, err := registry.ResolveTemplateFromName(ctx, r, id, version)
	if err != nil {
		if errors.Is(err, registry.ErrNotFound) {
			s.addError(fmt.Errorf("version '%s' not found", version))
			return
		}
		s.addError(err)
		return
	}

	// VCS-backed templates (e.g. those sourced from GitHub or GitLab) are versioned by
	// their repository, not the registry, so a specific version cannot be requested.
	switch template.Source {
	case "github", "gitlab":
		s.addError(fmt.Errorf(
			"template %q is VCS-backed and does not support specific versions", template.Name))
		return
	}

	s.addTemplate(registryTemplate{template, r, s})
}

